/*
 * 3D MTR rail renderer for MapLibre GL JS.
 * Station platform elevations are direct CSDI anchors; track heights between
 * them are estimates generated by scripts/build_mtr_3d_railways.cjs.
 */
window.Mtr3DRailways = (() => {
  const EARTH_RADIUS = 6371008.8;
  const DEG = Math.PI / 180;
  const TUBE_SIDES = 24;
  const STRIDE_FLOATS = 13;
  const PLATFORM_COLOR = [0.18, 0.72, 0.68, 0.58];

  function distance(a, b) {
    const lat1 = a[1] * DEG, lat2 = b[1] * DEG;
    const dLat = lat2 - lat1, dLon = (b[0] - a[0]) * DEG;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
    return 2 * EARTH_RADIUS * Math.atan2(Math.sqrt(h), Math.sqrt(Math.max(0, 1 - h)));
  }

  function normalize(vector) {
    const length = Math.hypot(vector[0], vector[1], vector[2]);
    return length > 1e-12 ? vector.map(value => value / length) : [1, 0, 0];
  }

  function subtract(a, b) {
    return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  }

  function dot(a, b) {
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  }

  function cross(a, b) {
    return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
  }

  function rotateAround(vector, axis, angle) {
    const cosine = Math.cos(angle), sine = Math.sin(angle);
    const crossed = cross(axis, vector);
    const along = dot(axis, vector) * (1 - cosine);
    return [
      vector[0] * cosine + crossed[0] * sine + axis[0] * along,
      vector[1] * cosine + crossed[1] * sine + axis[1] * along,
      vector[2] * cosine + crossed[2] * sine + axis[2] * along
    ];
  }

  function perpendicular(vector, tangent) {
    return normalize([
      vector[0] - tangent[0] * dot(vector, tangent),
      vector[1] - tangent[1] * dot(vector, tangent),
      vector[2] - tangent[2] * dot(vector, tangent)
    ]);
  }

  function parseColor(value) {
    const color = String(value || '#2563eb').trim();
    const short = /^#([\da-f]{3})$/i.exec(color);
    const full = /^#([\da-f]{6})$/i.exec(color);
    const hex = short ? [...short[1]].map(character => character + character).join('') : full?.[1];
    if (!hex) return [0.145, 0.388, 0.922, 0.96];
    return [0, 2, 4].map(index => parseInt(hex.slice(index, index + 2), 16) / 255).concat(0.96);
  }

  function projectionMatrixRelativeToOrigin(mainMatrix, origin) {
    // Mesh vertices are stored as small offsets from a local origin. Fold the
    // origin translation into MapLibre's camera matrix in JS double precision
    // so Float32 vertex attributes never have to represent absolute Mercator
    // coordinates near 0.5-1.0. At high zoom that quantization is several
    // screen pixels and makes a smooth tube visibly jump or break apart.
    const matrix = new Float32Array(mainMatrix);
    for (let row = 0; row < 4; row++) {
      matrix[12 + row] = mainMatrix[row] * origin.x + mainMatrix[4 + row] * origin.y +
        mainMatrix[8 + row] * origin.z + mainMatrix[12 + row];
    }
    return matrix;
  }

  function createLayer(maplibregl) {
    let map = null, gl = null, program = null, vertexBuffer = null, indexBuffer = null, vertexArray = null;
    let indexCount = 0, data = null, visible = false, exaggeration = 2, filterCodes = null;
    let attributes = null, uniforms = null;
    const localOrigin = maplibregl.MercatorCoordinate.fromLngLat([114.16, 22.34], 0);

    const layer = {
      id: 'mtr-3d-railway-network',
      type: 'custom',
      renderingMode: '3d',

      onAdd(mapInstance, context) {
        map = mapInstance;
        gl = context;
        const vertexShader = gl.createShader(gl.VERTEX_SHADER);
        gl.shaderSource(vertexShader, `#version 300 es
          precision highp float;
          uniform mat4 u_matrix;
          uniform float u_radius;
          in vec3 a_center;
          in vec3 a_normal;
          in vec4 a_color;
          in float a_radius_scale;
          in float a_dash;
          in float a_distance;
          out vec4 v_color;
          out vec3 v_normal;
          out float v_dash;
          out float v_distance;
          void main() {
            vec3 position = a_center + a_normal * u_radius * a_radius_scale;
            gl_Position = u_matrix * vec4(position, 1.0);
            v_color = a_color;
            v_normal = a_normal;
            v_dash = a_dash;
            v_distance = a_distance;
          }`);
        gl.compileShader(vertexShader);
        if (!gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS)) throw new Error('3D rail vertex shader: ' + gl.getShaderInfoLog(vertexShader));

        const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
        gl.shaderSource(fragmentShader, `#version 300 es
          precision highp float;
          in vec4 v_color;
          in vec3 v_normal;
          in float v_dash;
          in float v_distance;
          out vec4 fragColor;
          void main() {
            if (v_dash > 0.5 && mod(v_distance, 180.0) > 98.0) discard;
            vec3 normal = normalize(v_normal);
            vec3 light = normalize(vec3(-0.32, -0.42, 0.85));
            float diffuse = max(dot(normal, light), 0.0);
            float shade = 0.42 + 0.58 * diffuse + 0.16 * pow(diffuse, 10.0);
            fragColor = vec4(v_color.rgb * v_color.a * shade, v_color.a);
          }`);
        gl.compileShader(fragmentShader);
        if (!gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS)) throw new Error('3D rail fragment shader: ' + gl.getShaderInfoLog(fragmentShader));

        program = gl.createProgram();
        gl.attachShader(program, vertexShader);
        gl.attachShader(program, fragmentShader);
        gl.linkProgram(program);
        gl.deleteShader(vertexShader);
        gl.deleteShader(fragmentShader);
        if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error('3D rail shader link: ' + gl.getProgramInfoLog(program));

        attributes = {
          center: gl.getAttribLocation(program, 'a_center'),
          normal: gl.getAttribLocation(program, 'a_normal'),
          color: gl.getAttribLocation(program, 'a_color'),
          radiusScale: gl.getAttribLocation(program, 'a_radius_scale'),
          dash: gl.getAttribLocation(program, 'a_dash'),
          distance: gl.getAttribLocation(program, 'a_distance')
        };
        uniforms = {
          matrix: gl.getUniformLocation(program, 'u_matrix'),
          radius: gl.getUniformLocation(program, 'u_radius')
        };

        vertexBuffer = gl.createBuffer();
        indexBuffer = gl.createBuffer();
        vertexArray = gl.createVertexArray();
        configureVertexArray();
        rebuildBuffer();
      },

      onRemove(_map, context) {
        if (vertexBuffer) context.deleteBuffer(vertexBuffer);
        if (indexBuffer) context.deleteBuffer(indexBuffer);
        if (vertexArray) context.deleteVertexArray(vertexArray);
        if (program) context.deleteProgram(program);
        vertexBuffer = null; indexBuffer = null; vertexArray = null; program = null; gl = null; map = null;
      },

      render(context, args) {
        if (!visible || !vertexArray || !indexCount || !program) return;
        const previousProgram = context.getParameter(context.CURRENT_PROGRAM);
        const previousVertexArray = context.getParameter(context.VERTEX_ARRAY_BINDING);
        const center = map.getCenter();
        const meterScale = maplibregl.MercatorCoordinate.fromLngLat([center.lng, center.lat]).meterInMercatorCoordinateUnits();
        const pixelsPerMeter = 512 * Math.pow(2, map.getZoom()) * meterScale;
        // Keep the rail shell slim enough that nearby OSM track lines do not
        // intersect into sawtooth ridges at station approaches.
        // Keep a stable screen-space tube width. A 0.4 m minimum radius made
        // rails balloon to more than 10 px at close zoom, which exposed every
        // small bend and way join as a jagged block.
        const radiusMeters = Math.max(0.02, 1.25 / Math.max(pixelsPerMeter, 1e-9));
        context.useProgram(program);
        context.uniformMatrix4fv(uniforms.matrix, false,
          projectionMatrixRelativeToOrigin(args.defaultProjectionData.mainMatrix, localOrigin));
        context.uniform1f(uniforms.radius, radiusMeters * meterScale);
        context.bindVertexArray(vertexArray);
        context.drawElements(context.TRIANGLES, indexCount, context.UNSIGNED_INT, 0);
        context.bindVertexArray(previousVertexArray);
        context.useProgram(previousProgram);
      },

      setData(nextData) {
        data = nextData;
        rebuildBuffer();
      },

      setVisible(nextVisible) {
        visible = !!nextVisible;
        if (map) map.triggerRepaint();
      },

      setExaggeration(value) {
        exaggeration = Math.max(1, Math.min(8, Number(value) || 2));
        rebuildBuffer();
      },

      setFilter(codes) {
        filterCodes = codes && codes.length ? new Set(codes) : null;
        rebuildBuffer();
      }
    };

    function mercator(coordinate) {
      const altitude = Number(coordinate[2]) || 0;
      const point = maplibregl.MercatorCoordinate.fromLngLat([Number(coordinate[0]), Number(coordinate[1])], altitude * exaggeration);
      return [point.x - localOrigin.x, point.y - localOrigin.y, point.z - localOrigin.z];
    }

    function buildFrames(points, closed) {
      const last = points.length - 1;
      const uniqueCount = closed ? last : points.length;
      const tangents = new Array(uniqueCount);
      const frames = new Array(points.length);

      for (let index = 0; index < uniqueCount; index++) {
        const previousIndex = closed ? (index - 1 + uniqueCount) % uniqueCount : Math.max(0, index - 1);
        const nextIndex = closed ? (index + 1) % uniqueCount : Math.min(uniqueCount - 1, index + 1);
        let tangent = subtract(points[nextIndex], points[previousIndex]);
        if (Math.hypot(...tangent) < 1e-12) tangent = subtract(points[nextIndex], points[index]);
        if (Math.hypot(...tangent) < 1e-12) tangent = subtract(points[index], points[previousIndex]);
        tangents[index] = normalize(tangent);
      }

      const initialTangent = tangents[0];
      let initialNormal = cross(initialTangent, [0, 0, 1]);
      if (Math.hypot(...initialNormal) < 1e-8) initialNormal = cross(initialTangent, [1, 0, 0]);
      initialNormal = perpendicular(normalize(initialNormal), initialTangent);
      frames[0] = { normal: initialNormal, binormal: normalize(cross(initialTangent, initialNormal)) };

      for (let index = 1; index < uniqueCount; index++) {
        const previousTangent = tangents[index - 1], tangent = tangents[index];
        const previousFrame = frames[index - 1];
        let axis = cross(previousTangent, tangent);
        const sine = Math.hypot(...axis);
        const cosine = Math.max(-1, Math.min(1, dot(previousTangent, tangent)));
        let normal = previousFrame.normal;
        if (sine > 1e-10) {
          axis = axis.map(value => value / sine);
          normal = rotateAround(normal, axis, Math.atan2(sine, cosine));
        } else if (cosine < 0) {
          // A near-180° bend has no unique transport axis; use the previous
          // binormal so the section turns consistently instead of flipping.
          normal = rotateAround(normal, previousFrame.binormal, Math.PI);
        }
        normal = perpendicular(normal, tangent);
        const binormal = normalize(cross(tangent, normal));
        frames[index] = { normal, binormal };
      }

      if (closed && uniqueCount > 2) {
        const lastFrame = frames[uniqueCount - 1];
        const seamAxis = cross(tangents[uniqueCount - 1], tangents[0]);
        const seamSine = Math.hypot(...seamAxis);
        const seamCosine = Math.max(-1, Math.min(1, dot(tangents[uniqueCount - 1], tangents[0])));
        let closingNormal = lastFrame.normal;
        if (seamSine > 1e-10) {
          closingNormal = rotateAround(closingNormal, seamAxis.map(value => value / seamSine), Math.atan2(seamSine, seamCosine));
        } else if (seamCosine < 0) {
          closingNormal = rotateAround(closingNormal, lastFrame.binormal, Math.PI);
        }
        closingNormal = perpendicular(closingNormal, tangents[0]);
        const seamAngle = Math.atan2(dot(tangents[0], cross(closingNormal, frames[0].normal)), dot(closingNormal, frames[0].normal));
        for (let index = 1; index < uniqueCount; index++) {
          const correction = seamAngle * index / uniqueCount;
          const normal = normalize(rotateAround(frames[index].normal, tangents[index], correction));
          frames[index] = { normal, binormal: normalize(cross(tangents[index], normal)) };
        }
        frames[last] = { normal: frames[0].normal.slice(), binormal: frames[0].binormal.slice() };
      }
      return frames;
    }

    function interpolateCoordinate(a, b, fraction) {
      return [
        a[0] + (b[0] - a[0]) * fraction,
        a[1] + (b[1] - a[1]) * fraction,
        (Number(a[2]) || 0) + ((Number(b[2]) || 0) - (Number(a[2]) || 0)) * fraction
      ];
    }

    function roundCorners(coordinates, radiusMeters = 18) {
      if (coordinates.length < 3 || radiusMeters <= 0) return coordinates.map(coordinate => coordinate.slice());
      const last = coordinates.length - 1;
      const closed = last > 2 && coordinates[0][0] === coordinates[last][0] && coordinates[0][1] === coordinates[last][1];
      const points = closed ? coordinates.slice(0, -1) : coordinates;
      if (points.length < 3) return coordinates.map(coordinate => coordinate.slice());
      const result = [];
      const start = closed ? 0 : 1;
      const end = closed ? points.length : points.length - 1;

      if (!closed) result.push(points[0].slice());
      for (let index = start; index < end; index++) {
        const previousIndex = (index - 1 + points.length) % points.length;
        const nextIndex = (index + 1) % points.length;
        const previous = points[previousIndex], current = points[index], next = points[nextIndex];
        const incoming = distance(previous, current), outgoing = distance(current, next);
        if (incoming < 0.05 || outgoing < 0.05) {
          result.push(current.slice());
          continue;
        }
        // Use nearly half of short OSM segments for the curve transition.
        // The earlier 24% trim left a visible corner at every dense way node.
        const cut = Math.min(radiusMeters, incoming * 0.45, outgoing * 0.45);
        const before = interpolateCoordinate(current, previous, cut / incoming);
        const after = interpolateCoordinate(current, next, cut / outgoing);
        result.push(before);
        for (let step = 1; step < 9; step++) {
          const t = step / 9, inverse = 1 - t;
          result.push([
            inverse * inverse * before[0] + 2 * inverse * t * current[0] + t * t * after[0],
            inverse * inverse * before[1] + 2 * inverse * t * current[1] + t * t * after[1],
            inverse * inverse * before[2] + 2 * inverse * t * current[2] + t * t * after[2]
          ]);
        }
        result.push(after);
      }
      if (closed) result.push(result[0].slice());
      else result.push(points[points.length - 1].slice());
      return result;
    }

    function mergeRailSegments(features) {
      const grouped = new Map(), platforms = [];
      const keyFor = coordinate => Number(coordinate[0]).toFixed(7) + ',' + Number(coordinate[1]).toFixed(7);
      for (const feature of features || []) {
        const properties = feature.properties || {};
        if (properties.kind === 'platform') { platforms.push(feature); continue; }
        const lines = feature.geometry?.type === 'LineString' ? [feature.geometry.coordinates]
          : feature.geometry?.type === 'MultiLineString' ? feature.geometry.coordinates : [];
        const groupKey = String(properties.code || '') + '|' + (properties.branch ? '1' : '0');
        if (!grouped.has(groupKey)) grouped.set(groupKey, []);
        for (const coordinates of lines) {
          if (coordinates?.length < 2) continue;
          grouped.get(groupKey).push({
            properties,
            coordinates: coordinates.map(coordinate => coordinate.slice()),
            startKey: keyFor(coordinates[0]),
            endKey: keyFor(coordinates[coordinates.length - 1])
          });
        }
      }

      const mergedFeatures = [];
      for (const edges of grouped.values()) {
        const incident = new Map();
        edges.forEach((edge, index) => {
          for (const end of ['start', 'end']) {
            const key = end === 'start' ? edge.startKey : edge.endKey;
            if (!incident.has(key)) incident.set(key, []);
            incident.get(key).push({ edgeIndex: index, end });
          }
        });

        // OSM route relations are split into many ways, and a shared node can
        // have degree > 2 where parallel tracks or switches meet. Pair the
        // two most natural through-going ends at each node (straightest path,
        // then closest rail height) so tube caps do not remain at every split.
        const connections = new Map();
        const endId = (edgeIndex, end) => `${edgeIndex}:${end}`;
        const endpointCoordinate = (edgeIndex, end) => {
          const coordinates = edges[edgeIndex].coordinates;
          return end === 'start' ? coordinates[0] : coordinates[coordinates.length - 1];
        };
        const outwardVector = (edgeIndex, end) => {
          const coordinates = edges[edgeIndex].coordinates;
          const atNode = end === 'start' ? coordinates[0] : coordinates[coordinates.length - 1];
          const next = end === 'start' ? coordinates[1] : coordinates[coordinates.length - 2];
          const latitude = atNode[1] * DEG;
          return normalize([(next[0] - atNode[0]) * Math.cos(latitude), next[1] - atNode[1], ((Number(next[2]) || 0) - (Number(atNode[2]) || 0)) / EARTH_RADIUS / DEG]);
        };
        for (const ends of incident.values()) {
          if (ends.length < 2) continue;
          const candidates = [];
          for (let a = 0; a < ends.length; a++) {
            for (let b = a + 1; b < ends.length; b++) {
              const first = ends[a], second = ends[b];
              if (first.edgeIndex === second.edgeIndex) continue;
              const firstPoint = endpointCoordinate(first.edgeIndex, first.end);
              const secondPoint = endpointCoordinate(second.edgeIndex, second.end);
              const elevationGap = Math.abs((Number(firstPoint[2]) || 0) - (Number(secondPoint[2]) || 0));
              if (elevationGap > 1.5) continue;
              const continuation = dot(outwardVector(first.edgeIndex, first.end), outwardVector(second.edgeIndex, second.end));
              // Reject sharp turnbacks and crossings; a railway continuation
              // should leave the node in roughly the opposite direction.
              if (continuation > 0.5) continue;
              candidates.push({ first, second, score: (continuation + 1) + elevationGap * 0.08 });
            }
          }
          candidates.sort((a, b) => a.score - b.score);
          const paired = new Set();
          for (const candidate of candidates) {
            const firstId = endId(candidate.first.edgeIndex, candidate.first.end);
            const secondId = endId(candidate.second.edgeIndex, candidate.second.end);
            if (paired.has(firstId) || paired.has(secondId)) continue;
            paired.add(firstId);
            paired.add(secondId);
            connections.set(firstId, candidate.second);
            connections.set(secondId, candidate.first);
          }
        }

        const order = edges.map((_edge, index) => index).sort((a, b) => {
          const aConnected = Number(connections.has(endId(a, 'start'))) + Number(connections.has(endId(a, 'end')));
          const bConnected = Number(connections.has(endId(b, 'start'))) + Number(connections.has(endId(b, 'end')));
          return aConnected - bConnected;
        });
        const used = new Uint8Array(edges.length);
        for (const seedIndex of order) {
          if (used[seedIndex]) continue;
          const seed = edges[seedIndex];
          const startLinked = connections.has(endId(seedIndex, 'start'));
          const endLinked = connections.has(endId(seedIndex, 'end'));
          const reverseSeed = startLinked && !endLinked;
          let coordinates = reverseSeed ? seed.coordinates.slice().reverse() : seed.coordinates.slice();
          let currentEnd = reverseSeed ? 'start' : 'end';
          let currentEdgeIndex = seedIndex;
          used[seedIndex] = 1;

          while (true) {
            const nextEnd = connections.get(endId(currentEdgeIndex, currentEnd));
            if (!nextEnd || used[nextEnd.edgeIndex]) break;
            const nextIndex = nextEnd.edgeIndex;
            const next = edges[nextIndex];
            let oriented;
            if (nextEnd.end === 'start') oriented = next.coordinates;
            else oriented = next.coordinates.slice().reverse();
            const prior = coordinates[coordinates.length - 1], first = oriented[0];
            if (Math.abs((Number(prior[2]) || 0) - (Number(first[2]) || 0)) > 1.5) break;
            const joinElevation = ((Number(prior[2]) || 0) + (Number(first[2]) || 0)) / 2;
            prior[2] = joinElevation;
            first[2] = joinElevation;
            coordinates.push(...oriented.slice(1).map(coordinate => coordinate.slice()));
            used[nextIndex] = 1;
            currentEnd = nextEnd.end === 'start' ? 'end' : 'start';
            currentEdgeIndex = nextIndex;
          }

          mergedFeatures.push({ type: 'Feature', properties: seed.properties, geometry: { type: 'LineString', coordinates } });
        }
      }
      return platforms.concat(mergedFeatures);
    }

    function appendTube(vertices, indices, coordinates, color, radiusScale, dashed) {
      if (!Array.isArray(coordinates) || coordinates.length < 2) return;
      const cleanCoordinates = [];
      for (const coordinate of coordinates) {
        if (!Array.isArray(coordinate) || coordinate.length < 2 || !Number.isFinite(Number(coordinate[0])) || !Number.isFinite(Number(coordinate[1]))) continue;
        const previous = cleanCoordinates[cleanCoordinates.length - 1];
        if (previous && distance(previous, coordinate) < 0.25 && Math.abs((Number(previous[2]) || 0) - (Number(coordinate[2]) || 0)) < 0.1) continue;
        cleanCoordinates.push(coordinate);
      }
      if (cleanCoordinates.length < 2) return;
      const smoothCoordinates = roundCorners(cleanCoordinates, radiusScale < 0.5 ? 0 : 45);
      const points = smoothCoordinates.map(mercator);
      const lastIndex = points.length - 1;
      const closed = lastIndex > 2 && smoothCoordinates[0][0] === smoothCoordinates[lastIndex][0] && smoothCoordinates[0][1] === smoothCoordinates[lastIndex][1];
      const frames = buildFrames(points, closed);
      const base = vertices.length / STRIDE_FLOATS;
      const traveled = [0];
      for (let i = 1; i < smoothCoordinates.length; i++) traveled[i] = traveled[i - 1] + distance(smoothCoordinates[i - 1], smoothCoordinates[i]);

      for (let i = 0; i < points.length; i++) {
        const { normal, binormal } = frames[i];
        for (let side = 0; side < TUBE_SIDES; side++) {
          const angle = (side / TUBE_SIDES) * Math.PI * 2;
          const cos = Math.cos(angle), sin = Math.sin(angle);
          const radial = [normal[0] * cos + binormal[0] * sin, normal[1] * cos + binormal[1] * sin, normal[2] * cos + binormal[2] * sin];
          vertices.push(...points[i], ...radial, ...color, radiusScale, dashed ? 1 : 0, traveled[i]);
        }
      }

      const sectionCount = points.length - 1;
      for (let i = 0; i < sectionCount; i++) {
        for (let side = 0; side < TUBE_SIDES; side++) {
          const nextSide = (side + 1) % TUBE_SIDES;
          const a = base + i * TUBE_SIDES + side;
          const b = base + (i + 1) * TUBE_SIDES + side;
          const c = base + (i + 1) * TUBE_SIDES + nextSide;
          const d = base + i * TUBE_SIDES + nextSide;
          indices.push(a, b, d, b, c, d);
        }
      }
    }

    function configureVertexArray() {
      if (!gl || !vertexBuffer || !indexBuffer || !vertexArray) return;
      const previousVertexArray = gl.getParameter(gl.VERTEX_ARRAY_BINDING);
      const previousArrayBuffer = gl.getParameter(gl.ARRAY_BUFFER_BINDING);
      gl.bindVertexArray(vertexArray);
      gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
      const stride = STRIDE_FLOATS * Float32Array.BYTES_PER_ELEMENT;
      const pointers = [
        [attributes.center, 3, 0], [attributes.normal, 3, 3 * 4], [attributes.color, 4, 6 * 4],
        [attributes.radiusScale, 1, 10 * 4], [attributes.dash, 1, 11 * 4], [attributes.distance, 1, 12 * 4]
      ];
      for (const [location, size, offset] of pointers) {
        gl.enableVertexAttribArray(location);
        gl.vertexAttribPointer(location, size, gl.FLOAT, false, stride, offset);
      }
      gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
      gl.bindVertexArray(previousVertexArray);
      gl.bindBuffer(gl.ARRAY_BUFFER, previousArrayBuffer);
    }

    function rebuildBuffer() {
      if (!gl || !vertexBuffer || !indexBuffer) return;
      const vertices = [], indices = [];
      const features = mergeRailSegments(data?.features).sort((a, b) =>
        (a.properties?.kind === 'platform' ? 0 : 1) - (b.properties?.kind === 'platform' ? 0 : 1));
      for (const feature of features) {
        const properties = feature.properties || {};
        const lineCodes = Array.isArray(properties.lineCodes) ? properties.lineCodes : [];
        if (filterCodes && !filterCodes.has(properties.code) && !lineCodes.some(code => filterCodes.has(code))) continue;
        const isPlatform = properties.kind === 'platform';
        const color = isPlatform ? PLATFORM_COLOR : parseColor(properties.color);
        const radiusScale = isPlatform ? 0.2 : 1;
        const dashed = !!properties.branch;
        let lines = [];
        if (feature.geometry?.type === 'LineString') lines = [feature.geometry.coordinates];
        else if (feature.geometry?.type === 'MultiLineString') lines = feature.geometry.coordinates;
        for (const coordinates of lines) appendTube(vertices, indices, coordinates, color, radiusScale, dashed);
      }
      indexCount = indices.length;
      const previousArrayBuffer = gl.getParameter(gl.ARRAY_BUFFER_BINDING);
      const previousElementBuffer = gl.getParameter(gl.ELEMENT_ARRAY_BUFFER_BINDING);
      gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
      gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
      gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(indices), gl.STATIC_DRAW);
      gl.bindBuffer(gl.ARRAY_BUFFER, previousArrayBuffer);
      // Element-array binding belongs to the active VAO; restore the map's binding.
      gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, previousElementBuffer);
      if (map) map.triggerRepaint();
    }

    return layer;
  }

  return { createLayer };
})();
